```python
class Stack:
    def __init__(self):
        self.items = []

    def is_empty(self):
        return len(self.items) == 0

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()

    def peek(self):
        if not self.is_empty():
            return self.items[-1]

    def size(self):
        return len(self.items)

class Queue:
    def __init__(self):
        self.items = Stack()

    def is_empty(self):
        return self.items.is_empty()

    def enqueue(self, item):
        self.items.push(item)

    def dequeue(self):
        if not self.is_empty():
            return self.items.pop()

    def front(self):
        if not self.is_empty():
            return self.items.peek()

    def size(self):
        return self.items.size()
```

